import { describe, it, expect } from 'vitest';
import { render, screen } from '@testing-library/react';
import UserStats, { User } from './UserStats';

describe('UserStats', () => {
  it('displays correct statistics for active and inactive users', () => {
    const users: User[] = [
      { id: 1, name: 'User 1', isActive: true },
      { id: 2, name: 'User 2', isActive: false },
      { id: 3, name: 'User 3', isActive: true },
      { id: 4, name: 'User 4', isActive: true },
    ];

    render(<UserStats users={users} />);

    // Active users: 3
    // Inactive users: 1
    // Percentage: (3/4) * 100 = 75.0%

    expect(screen.getByText('Active Users')).toBeDefined();
    expect(screen.getByText('3')).toBeDefined();

    expect(screen.getByText('Inactive Users')).toBeDefined();
    expect(screen.getByText('1')).toBeDefined();

    expect(screen.getByText('Active Percentage')).toBeDefined();
    expect(screen.getByText('75.0%')).toBeDefined();
  });

  it('handles empty user list gracefully', () => {
    const users: User[] = [];

    render(<UserStats users={users} />);

    expect(screen.getByText('0')).toBeDefined(); // Active & Inactive counts
    expect(screen.getByText('0.0%')).toBeDefined();
  });

  it('handles all inactive users', () => {
    const users: User[] = [
      { id: 1, name: 'User 1', isActive: false },
      { id: 2, name: 'User 2', isActive: false },
    ];

    render(<UserStats users={users} />);

    expect(screen.getByText('Active Users')).toBeDefined();
    // Use regex or stricter query if multiple '0's appear
    // But here we expect 0 for active users

    // Check specific values
    const values = screen.getAllByText('0');
    expect(values.length).toBeGreaterThanOrEqual(1); // Active count should be 0

    expect(screen.getByText('2')).toBeDefined(); // Inactive count
    expect(screen.getByText('0.0%')).toBeDefined(); // Percentage
  });
});

